SELECT p.id, p.symbol, s.id AS signal_id, s.decision, s.atr_entry_type, s.atr_recommended_position_percent, b.execution_reason, p.realized_pnl, p.close_reason, p.opened_at FROM paper_position p JOIN trade_signal s ON s.id = p.signal_id LEFT JOIN wallet_trade b ON b.signal_id = p.signal_id AND b.side = 'BUY' AND b.status = 'EXECUTED' WHERE p.closed_at IS NOT NULL AND s.atr_entry_type IN ('NO_ENTRY','WAIT_FOR_RETRACEMENT') ORDER BY p.opened_at LIMIT 50